require "test_helper"

# The Solid Errors MCP tools are admin only (generated by maquina:solid_errors):
# only someone on the backstage list sees them. A member's token must not learn
# they exist: they are absent from tools/list and a call gets the same -32602
# as an unknown tool. McpTestHelper turns any MCP feature flag on and puts
# mcp_admin on the backstage list, so access is the only gate tested.
class Mcp::Tools::SolidErrorsTest < ActionDispatch::IntegrationTest
  TOOLS = Mcp::Tools::SolidErrors::DEFINITIONS.map { |definition| definition[:name] }
  ARGUMENTS = {"get_failure" => {fingerprint: "unknown"}, "resolve_failure" => {fingerprint: "unknown"}}.freeze

  test "an admin sees the tools" do
    assert_equal TOOLS, TOOLS & listed_tools(users(:mcp_admin))
  end

  test "a member does not see the tools" do
    assert_empty TOOLS & listed_tools(users(:mcp_member))
  end

  test "a member calling any of the tools gets unknown tool" do
    token = oauth_token_for(users(:mcp_member), scope: "read write")

    TOOLS.each do |name|
      mcp_post({jsonrpc: "2.0", id: 1, method: "tools/call", params: {name: name, arguments: ARGUMENTS.fetch(name, {})}}, token: token)

      assert_equal(-32602, response.parsed_body.dig("error", "code"), name)
    end
  end

  test "list_failures puts the most recently seen error first" do
    freeze_time
    busy = create_error("NoMethodError", occurrences: 3, at: 2.hours.ago)
    recent = create_error("ArgumentError", occurrences: 1, at: 5.minutes.ago)

    failures = call_tool("list_failures")["failures"]

    assert_equal [recent.fingerprint, busy.fingerprint], failures.map { |failure| failure["fingerprint"] }
    assert_equal [1, 3], failures.map { |failure| failure["occurrences"] }
    assert_equal 5.minutes.ago.utc.iso8601, failures.first["last_seen"]
  end

  test "top_exceptions puts the error with the most occurrences first" do
    busy = create_error("NoMethodError", occurrences: 3, at: 2.hours.ago)
    create_error("ArgumentError", occurrences: 1, at: 5.minutes.ago)

    top = call_tool("top_exceptions")["top_exceptions"]

    assert_equal busy.fingerprint, top.first["fingerprint"]
    assert_equal 3, top.first["occurrences"]
  end

  test "get_failure returns the job context redacted and the backtrace" do
    error = create_error("ArgumentError", occurrences: 1,
      context: {"active_job" => "ChargeJob", "job_id" => "job-1", "arguments" => [{"amount" => 10, "card_number" => "4242"}]})

    failure = call_tool("get_failure", {fingerprint: error.fingerprint})

    assert_equal "ArgumentError", failure["exception"]
    assert_equal({"class" => "ChargeJob", "arguments" => [{"amount" => 10, "card_number" => "[REDACTED]"}], "job_id" => "job-1"}, failure["job"])
    assert_equal ["app/models/order.rb:1:in 'charge'", "app/controllers/orders_controller.rb:9"], failure["backtrace"]
  end

  test "get_failure for an unknown fingerprint is not found" do
    result = call_tool_result("get_failure", {fingerprint: "unknown"})

    assert result["isError"]
    assert_equal Mcp::ToolError::NOT_FOUND, result.dig("content", 0, "text")
  end

  test "resolve_failure marks the error resolved and it leaves the list" do
    skip "Read-only tools: rails g maquina:solid_errors --mcp-write adds resolve_failure" unless TOOLS.include?("resolve_failure")
    error = create_error("NoMethodError", occurrences: 1)

    resolved = call_tool("resolve_failure", {fingerprint: error.fingerprint}, scope: "read write")

    assert_equal error.fingerprint, resolved["fingerprint"]
    assert error.reload.resolved_at
    assert_empty call_tool("list_failures")["failures"]
  end

  private

  def listed_tools(user)
    mcp_post({jsonrpc: "2.0", id: 1, method: "tools/list", params: {}}, token: oauth_token_for(user, scope: "read write"))
    response.parsed_body.dig("result", "tools").map { |tool| tool["name"] }
  end

  def call_tool_result(name, arguments = {}, scope: "read")
    mcp_post({method: "tools/call", params: {name: name, arguments: arguments}}, token: oauth_token_for(users(:mcp_admin), scope: scope))
    assert_response :success
    response.parsed_body["result"]
  end

  def call_tool(name, arguments = {}, scope: "read")
    result = call_tool_result(name, arguments, scope: scope)
    assert_equal false, result["isError"], result.dig("content", 0, "text")
    result["structuredContent"]
  end

  def create_error(exception_class, occurrences:, at: Time.current, context: {})
    error = SolidErrors::Error.create!(exception_class: exception_class, message: "#{exception_class} raised",
      severity: "error", source: "application", fingerprint: SecureRandom.hex(32))
    occurrences.times do |index|
      error.occurrences.create!(context: context, created_at: at - index.minutes,
        backtrace: "app/models/order.rb:1:in 'charge'\napp/controllers/orders_controller.rb:9\n")
    end
    error
  end
end
